PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, full_name TEXT NOT NULL, email TEXT NOT NULL COLLATE NOCASE UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('student','lecturer','staff','technician','admin')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS service_requests(id INTEGER PRIMARY KEY, request_number TEXT NOT NULL UNIQUE, requester_id INTEGER NOT NULL REFERENCES users(id), title TEXT NOT NULL, category TEXT NOT NULL, description TEXT NOT NULL, building TEXT NOT NULL, room_number TEXT NOT NULL, priority TEXT NOT NULL CHECK(priority IN ('Low','Medium','High')), status TEXT NOT NULL DEFAULT 'Pending' CHECK(status IN ('Pending','In Progress','Completed')), assigned_technician_id INTEGER REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS request_attachments(id INTEGER PRIMARY KEY, request_id INTEGER NOT NULL REFERENCES service_requests(id) ON DELETE CASCADE, filename TEXT NOT NULL, file_path TEXT NOT NULL, mime_type TEXT NOT NULL, file_size INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS assignments(id INTEGER PRIMARY KEY, request_id INTEGER NOT NULL REFERENCES service_requests(id), technician_id INTEGER NOT NULL REFERENCES users(id), assigned_by INTEGER NOT NULL REFERENCES users(id), assigned_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS status_history(id INTEGER PRIMARY KEY, request_id INTEGER NOT NULL REFERENCES service_requests(id), old_status TEXT, new_status TEXT NOT NULL, changed_by INTEGER NOT NULL REFERENCES users(id), note TEXT, changed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS notifications(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), request_id INTEGER NOT NULL REFERENCES service_requests(id), message TEXT NOT NULL, is_read INTEGER NOT NULL DEFAULT 0 CHECK(is_read IN (0,1)), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_requests_owner ON service_requests(requester_id); CREATE INDEX IF NOT EXISTS idx_requests_tech ON service_requests(assigned_technician_id); CREATE INDEX IF NOT EXISTS idx_notifications_user ON notifications(user_id); CREATE INDEX IF NOT EXISTS idx_history_request ON status_history(request_id);
CREATE TABLE IF NOT EXISTS schema_migrations(version TEXT PRIMARY KEY);
